# Generated by build.py from recipe.yml for recipe ftp-check-an-app-uploaded-the-right-file. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'expected.csv'), "id,region,total`n1,north,42`n2,south,17`n")
[IO.File]::WriteAllText((Join-Path $PWD 'app.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# app.sh FTP-URL [broken]: the app under test. It writes tonight's export, nightly.csv, and uploads it to`n# exports/nightly.csv under the FTP URL (ending in /), making the folder if need be. Given broken, it leaves out`n# the last row, as a bug would. A failed upload is curl's exit code.`nrows='1,north,42`n2,south,17'`nif [ `"`$2`" = broken ]; then rows='1,north,42'; fi`nprintf 'id,region,total\n%s\n' `"`$rows`" > nightly.csv`ncurl -sS --ftp-create-dirs -T nightly.csv `"`${1}exports/nightly.csv`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# check.sh FILE-URL EXPECTED: fetches the uploaded file over HTTP into arrived.csv and compares it, byte for`n# byte, with EXPECTED. Exit 1 when they differ; a failed fetch (a 404 included, through -f) is curl's exit code.`ncurl -sS -f -o arrived.csv `"`$1`" || exit`nif cmp -s `"`$2`" arrived.csv; then echo `"matches `$2`"; exit 0; fi`necho `"differs from `$2: expected `$(wc -c < `"`$2`" | tr -d ' ') bytes, arrived `$(wc -c < arrived.csv | tr -d ' ')`"`nexit 1`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', 'ftp://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh app.sh ftp://127.0.0.1:8080/ && sh check.sh http://127.0.0.1:8081/exports/nightly.csv expected.csv } finally { Stop-Process $server0 }
